-- =============================================================================
-- 192_icd10_search_no_diacritics.sql
-- Them cot NameNoDiacritics cho IcdCodes de TIM KIEM KHONG DAU.
--
-- Vi sao: DB dung collation Vietnamese_CI_AS -- CI = khong phan biet hoa/thuong,
-- nhung AS = PHAN BIET DAU. Nen LIKE N'%tang huyet ap%' KHONG khop 'tang huyet ap'
-- co dau. Bac si dang kham, go nhanh khong dau -> man hinh bao khong co gi.
-- Voi 41 ma seed cu thi khong ai nhan ra; co 15.554 ma thi day la rao can that.
--
-- Vi sao KHONG ep COLLATE Vietnamese_CI_AI ngay trong WHERE: lam vay la ep kieu
-- tren cot -> MAT INDEX, moi lan go phim la quet toan bang 15.554 dong.
-- Cot rieng thi index duoc va truy van van sargable.
--
-- Idempotent: them cot neu chua co; chi UPDATE dong con NULL.
-- =============================================================================

SET QUOTED_IDENTIFIER ON;
SET NOCOUNT ON;

IF NOT EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS
               WHERE TABLE_NAME='IcdCodes' AND COLUMN_NAME='NameNoDiacritics')
    ALTER TABLE IcdCodes ADD NameNoDiacritics nvarchar(500) NULL;
GO

SET QUOTED_IDENTIFIER ON;
SET NOCOUNT ON;

IF OBJECT_ID('tempdb..#IcdND') IS NOT NULL DROP TABLE #IcdND;
CREATE TABLE #IcdND (
    Code nvarchar(20)  COLLATE DATABASE_DEFAULT NOT NULL PRIMARY KEY,
    NoDi nvarchar(500) COLLATE DATABASE_DEFAULT NULL
);

