UPDATE c SET c.NameNoDiacritics = t.NoDi
FROM IcdCodes c JOIN #IcdND t ON t.Code = c.Code
WHERE c.NameNoDiacritics IS NULL;
PRINT CONCAT('192: da dien ban khong dau cho ', @@ROWCOUNT, ' ma ICD.');
DROP TABLE #IcdND;
GO

-- Index phuc vu truy van tim kiem (LIKE '%kw%' khong dung duoc seek, nhung index
-- nay van giup scan hep hon vi chi doc 2 cot thay vi ca bang).
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name='IX_IcdCodes_NameNoDiacritics')
    CREATE INDEX IX_IcdCodes_NameNoDiacritics ON IcdCodes(NameNoDiacritics) INCLUDE (Code, Name);
GO
